CREATE TABLE IF NOT EXISTS ap_users(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, failed_logins integer NOT NULL DEFAULT 0, locked_until timestamptz, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS ap_sessions(token_hash text PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,user_id) REFERENCES ap_users(tenant_id,id));
CREATE TABLE IF NOT EXISTS ap_purchases(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, item_id text NOT NULL, amount text NOT NULL CHECK(amount ~ '^[0-9]+\.[0-9]{2}$'), currency text NOT NULL CHECK(currency='USD'), merchant_id text NOT NULL, state text NOT NULL CHECK(state IN ('DRAFT','REVIEWED','AUTHORIZATION_PENDING','APPROVED','ORDER_CREATED','PAYER_APPROVED','CAPTURE_PENDING','UNKNOWN','COMPLETED','REJECTED','EXPIRED','REVOKED','CANCELED','FAILED')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,user_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES ap_users(tenant_id,id));
CREATE TABLE IF NOT EXISTS ap_approvals(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, purchase_id uuid NOT NULL UNIQUE, authority_id text NOT NULL, action_hash text NOT NULL, expires_at timestamptz NOT NULL, reserved_attempt_id uuid, FOREIGN KEY(tenant_id,user_id,purchase_id) REFERENCES ap_purchases(tenant_id,user_id,id));
CREATE TABLE IF NOT EXISTS ap_orders(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, purchase_id uuid NOT NULL UNIQUE, provider_order_id text NOT NULL UNIQUE, request_id uuid NOT NULL UNIQUE, FOREIGN KEY(tenant_id,user_id,purchase_id) REFERENCES ap_purchases(tenant_id,user_id,id));
CREATE TABLE IF NOT EXISTS ap_attempts(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, purchase_id uuid NOT NULL UNIQUE, provider_order_id text NOT NULL, request_id uuid NOT NULL UNIQUE, state text NOT NULL CHECK(state IN ('CAPTURE_PENDING','UNKNOWN','COMPLETED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,user_id,purchase_id) REFERENCES ap_purchases(tenant_id,user_id,id));
CREATE TABLE IF NOT EXISTS ap_receipts(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, purchase_id uuid NOT NULL, attempt_id uuid NOT NULL UNIQUE REFERENCES ap_attempts(id), provider_capture_id text UNIQUE, outcome text NOT NULL, evidence jsonb NOT NULL, FOREIGN KEY(tenant_id,user_id,purchase_id) REFERENCES ap_purchases(tenant_id,user_id,id));
CREATE TABLE IF NOT EXISTS ap_audit(id bigserial PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, purchase_id uuid NOT NULL, event text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,user_id,purchase_id) REFERENCES ap_purchases(tenant_id,user_id,id));
